// Flashcards do Regimento Interno do TJSP: escritos a partir do texto oficial (atualizado em 30/04/2026).
window.FC_VDE = (window.FC_VDE || []).concat([
{"id":"tj_rit_001","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem compõe o Tribunal Pleno?","v":"Todos os desembargadores do Tribunal.","b":"RITJSP, art. 4º"},
{"id":"tj_rit_002","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem o Tribunal Pleno elege?","v":"Presidente, Vice-Presidente e Corregedor Geral da Justiça; os doze desembargadores eleitos do Órgão Especial e seus suplentes; Diretor, Vice-Diretor e conselho da Escola Paulista da Magistratura; e os desembargadores substitutos do TRE.","b":"RITJSP, art. 4º","p":"O Pleno elege os desembargadores substitutos do TRE; os juízes substitutos do TRE (classe dos magistrados) são eleitos pelo Órgão Especial (art. 13, II, d)."},
{"id":"tj_rit_003","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem convoca o Tribunal Pleno?","v":"O Presidente do Tribunal, previamente, por edital no órgão oficial; se ele se omitir, o Vice-Presidente.","b":"RITJSP, art. 5º"},
{"id":"tj_rit_004","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Como é composta a Mesa do Tribunal Pleno?","v":"Presidente, Vice-Presidente, Corregedor Geral e um ou dois desembargadores dentre os mais modernos presentes, que secretariam a sessão.","b":"RITJSP, art. 6º","p":"Secretariam os mais modernos (menos antigos), não os mais antigos."},
{"id":"tj_rit_005","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem resolve as questões de ordem no Tribunal Pleno?","v":"O Presidente, de imediato, ouvidos o Vice-Presidente e o Corregedor Geral. Qualquer desembargador pode pedir que conste em ata protesto contra ato da Mesa.","b":"RITJSP, art. 7º"},
{"id":"tj_rit_006","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quantos desembargadores formam o Órgão Especial e quem são os membros natos?","v":"Vinte e cinco. Presidente, Vice-Presidente e Corregedor Geral são membros natos; os demais vêm das classes de antiguidade e de eleitos.","b":"RITJSP, art. 8º","p":"25 integrantes no total; 12 deles são eleitos pelo Pleno (art. 4º, II)."},
{"id":"tj_rit_007","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Como é ocupada a quinta cadeira do Órgão Especial destinada ao quinto constitucional?","v":"Alternadamente por desembargadores vindos do Ministério Público e da Advocacia.","b":"RITJSP, art. 8º, § 1º"},
{"id":"tj_rit_008","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Havendo vaga no Órgão Especial, em que prazo o Presidente convoca eleição?","v":"Em quinze dias, publicando edital com vinte dias de antecedência.","b":"RITJSP, art. 10, § 1º","p":"Troca comum: 15 dias para convocar e 20 dias de antecedência do edital."},
{"id":"tj_rit_009","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"O suplente de eleito do Órgão Especial pode recusar a substituição?","v":"Salvo impedimento ou justificativa, é obrigado a substituir; a recusa faz perder a suplência.","b":"RITJSP, art. 10, II"},
{"id":"tj_rit_010","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quando o eleito para o Órgão Especial começa a exercer o mandato?","v":"No dia imediato ao da eleição.","b":"RITJSP, art. 10, § 3º"},
{"id":"tj_rit_011","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"A suplência no Órgão Especial conta como mandato para fins de elegibilidade?","v":"Não. A suplência não é considerada exercício efetivo de mandato.","b":"RITJSP, art. 10, § 5º"},
{"id":"tj_rit_012","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Com quantos desembargadores, no mínimo, o Órgão Especial se instala?","v":"Com a presença de, no mínimo, treze desembargadores.","b":"RITJSP, art. 11"},
{"id":"tj_rit_013","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quando o Órgão Especial pode examinar proposta administrativa arquivada pelo Presidente?","v":"Quando, por maioria simples, acolher representação de qualquer integrante. Cabe também se o Presidente não pautar em quinze dias propostas prontas, ou para preservar a competência do órgão ou reexaminar matéria relevante.","b":"RITJSP, art. 12"},
{"id":"tj_rit_014","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem julga mandado de segurança contra ato do Conselho Superior da Magistratura?","v":"O Órgão Especial, que também julga MS e habeas data contra seus próprios atos, das Turmas Especiais, da Câmara Especial e de seus relatores.","b":"RITJSP, art. 13, I, b"},
{"id":"tj_rit_015","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem julga os incidentes de inconstitucionalidade?","v":"O Órgão Especial, mediante suscitação do órgão fracionário.","b":"RITJSP, arts. 13, I, d, e 193"},
{"id":"tj_rit_016","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem julga conflito de competência entre órgãos do Tribunal de Seções diferentes?","v":"O Órgão Especial.","b":"RITJSP, art. 13, I, e","p":"Conflito entre Câmaras e Grupos da mesma Seção: Turma Especial (art. 32, IV); conflito entre juízes: Câmara Especial (art. 33)."},
{"id":"tj_rit_017","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem julga arguição de impedimento ou suspeição de desembargador?","v":"O Órgão Especial, com o Presidente do Tribunal como relator.","b":"RITJSP, arts. 13, I, g, e 26, I, d","p":"Impedimento ou suspeição de juiz de primeiro grau vai à Câmara Especial (art. 33, I)."},
{"id":"tj_rit_018","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem julga as ações rescisórias dos acórdãos das Turmas Especiais?","v":"O Órgão Especial, que também julga as rescisórias de seus próprios acórdãos.","b":"RITJSP, art. 13, I, h"},
{"id":"tj_rit_019","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem instaura e decide processo disciplinar contra magistrado?","v":"O Órgão Especial, inclusive quanto ao afastamento preventivo da jurisdição.","b":"RITJSP, art. 13, II, g"},
{"id":"tj_rit_020","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem aprova a escala de plantão de segundo grau?","v":"O Órgão Especial, por proposta do Presidente do Tribunal.","b":"RITJSP, arts. 13, II, u, e 26, II, h","p":"A escala de plantão do primeiro grau é organizada pelo próprio Presidente."},
{"id":"tj_rit_021","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Qual o prazo do plano plurianual de gestão aprovado pelo Órgão Especial?","v":"Cinco anos, com relatórios semestrais de execução, ouvida a Comissão de Assuntos Administrativos.","b":"RITJSP, art. 13, II, x"},
{"id":"tj_rit_022","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem autoriza o nome de fóruns e prédios e a colocação de estátuas ou bustos?","v":"O Órgão Especial, ouvidos a Comissão de Honraria e Mérito e o Conselho Superior da Magistratura; é proibido homenagear pessoa viva.","b":"RITJSP, art. 13, II, t","p":"Nome de salas e dependências internas, retratos e placas: Conselho Superior da Magistratura (art. 16, XIV)."},
{"id":"tj_rit_023","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem elabora as listas tríplices das vagas de advogados, MP e juízes militares?","v":"O Órgão Especial. O Conselho Superior da Magistratura apenas apresenta a ele as listas do quinto.","b":"RITJSP, arts. 13, II, l, e 16, II"},
{"id":"tj_rit_024","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"O Órgão Especial pode reduzir a distribuição de processos a seus integrantes?","v":"Sim. A seu critério, pode reduzir, suspender ou interromper, por prazo determinado ou indeterminado, a distribuição dos processos das Câmaras e demais órgãos fracionários.","b":"RITJSP, art. 14"},
{"id":"tj_rit_025","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem compõe o Conselho Superior da Magistratura?","v":"Presidente do Tribunal (que o preside), Vice-Presidente, Corregedor Geral, Decano e Presidentes das Seções.","b":"RITJSP, art. 15","p":"O Decano integra o CSM, mas não a Câmara Especial de Presidentes."},
{"id":"tj_rit_026","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Como se resolve o empate no Conselho Superior da Magistratura?","v":"Prevalece o voto do presidente do Conselho.","b":"RITJSP, art. 15, § 2º"},
{"id":"tj_rit_027","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem julga as dúvidas de serventuários dos Registros Públicos?","v":"O Conselho Superior da Magistratura.","b":"RITJSP, art. 16, IV"},
{"id":"tj_rit_028","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem aprecia a suspeição por foro íntimo de juiz de primeiro grau?","v":"O Conselho Superior da Magistratura.","b":"RITJSP, art. 16, III","p":"Os incidentes de suspeição e impedimento de juiz de primeiro grau são julgados pela Câmara Especial (art. 33, I)."},
{"id":"tj_rit_029","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Qual o prazo de convocação dos juízes assessores dos órgãos de direção, cúpula e decanato?","v":"Dois anos, prorrogável com fundamentação. É vedado convocar parente até o terceiro grau dos ocupantes desses cargos.","b":"RITJSP, art. 16, X"},
{"id":"tj_rit_030","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem julga recursos de candidatos em concurso para cargos de servidores da Justiça?","v":"O Conselho Superior da Magistratura, que também julga recursos sobre inscrição no concurso da Magistratura.","b":"RITJSP, art. 16, VIII e XIII","p":"Reclamação contra a classificação no concurso da Magistratura é do Órgão Especial (art. 13, II, s)."},
{"id":"tj_rit_031","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem aprova a suspensão do expediente nos feriados municipais das comarcas do interior?","v":"O Conselho Superior da Magistratura.","b":"RITJSP, art. 16, XV"},
{"id":"tj_rit_032","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Qual o quórum para o Conselho Superior da Magistratura se reunir?","v":"Pelo menos dois ocupantes dos cargos de direção e mais dois de seus membros.","b":"RITJSP, art. 43, parágrafo único"},
{"id":"tj_rit_033","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quais cargos são de direção e quais são de cúpula?","v":"Direção: Presidente, Vice-Presidente e Corregedor Geral da Justiça. Cúpula: Presidentes das Seções.","b":"RITJSP, arts. 17 e 20"},
{"id":"tj_rit_034","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quando ocorre a eleição para os cargos de direção?","v":"Na segunda quarta-feira de novembro do ano em que terminam os mandatos, pelo Tribunal em composição plenária, presidido pelo Presidente.","b":"RITJSP, art. 17"},
{"id":"tj_rit_035","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Qual o prazo para renúncia dos candidatos elegíveis aos cargos de direção?","v":"Dez dias, aberto vinte e cinco dias antes da data da eleição.","b":"RITJSP, art. 18"},
{"id":"tj_rit_036","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quando há segundo escrutínio na eleição dos cargos de direção e como ele funciona?","v":"Quando ninguém alcança a maioria absoluta dos votos dos integrantes efetivos. Concorrem os dois mais votados e vence quem tiver a maioria dos votantes, contados brancos e nulos.","b":"RITJSP, art. 19"},
{"id":"tj_rit_037","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Como se desempata a eleição para cargo de direção?","v":"Vence o candidato mais antigo.","b":"RITJSP, art. 19, § 3º"},
{"id":"tj_rit_038","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"O que acontece se nenhum candidato for eleito nem no segundo escrutínio?","v":"Faz-se outra eleição em no máximo cinco dias, sem esses candidatos, convidando os seguintes na antiguidade. A regra vale também para candidato único.","b":"RITJSP, art. 19, §§ 1º e 2º"},
{"id":"tj_rit_039","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem elege os Presidentes das Seções e quando?","v":"Os integrantes de cada Seção, no mesmo dia da eleição de direção, mediante inscrição. No segundo escrutínio basta maioria simples.","b":"RITJSP, art. 20"},
{"id":"tj_rit_040","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Vagando cargo de direção ou de cúpula no curso do mandato, o que se faz?","v":"Convoca-se eleição para o período restante. Se faltarem menos de seis meses, não há eleição: ocorre a substituição regimental.","b":"RITJSP, art. 21"},
{"id":"tj_rit_041","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Como é a votação nas eleições do Tribunal?","v":"Secreta e, preferencialmente, por meio eletrônico.","b":"RITJSP, art. 22"},
{"id":"tj_rit_042","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem substitui o Presidente do Tribunal?","v":"O Vice-Presidente e, na falta deste, o Decano.","b":"RITJSP, art. 24"},
{"id":"tj_rit_043","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem substitui o Vice-Presidente e o Corregedor Geral?","v":"O Decano; e o Decano é substituído pelo desembargador seguinte na antiguidade, admitida recusa.","b":"RITJSP, art. 24, § 1º"},
{"id":"tj_rit_044","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem substitui o Presidente de Seção?","v":"O desembargador mais antigo da Seção ou, se impedido, o seguinte, admitida recusa.","b":"RITJSP, art. 24, § 3º"},
{"id":"tj_rit_045","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Desembargador eleito para o TRE pode substituir em cargo de direção ou de cúpula?","v":"Não. Exercendo função no TRE, efetiva ou por convocação, ele fica impedido.","b":"RITJSP, art. 24, § 6º"},
{"id":"tj_rit_046","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Que jurisdição exercem os ocupantes dos cargos de direção e de cúpula e o Decano?","v":"Somente a própria do cargo, ressalvados os votos no Órgão Especial e vinculação anterior.","b":"RITJSP, art. 25"},
{"id":"tj_rit_047","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem aprecia pedido de suspensão de segurança ou de liminar concedida em primeiro grau contra o Poder Público?","v":"O Presidente do Tribunal.","b":"RITJSP, art. 26, I, b"},
{"id":"tj_rit_048","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem organiza a pauta do Órgão Especial, do Conselho Superior da Magistratura e da Comissão de Organização Judiciária?","v":"O Presidente do Tribunal, que também preside as sessões do Plenário, do Órgão Especial e do CSM.","b":"RITJSP, art. 26, II, k e m"},
{"id":"tj_rit_049","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Até quando o Presidente apresenta ao Órgão Especial o relatório dos trabalhos do ano anterior?","v":"Até a última sessão ordinária de fevereiro, ainda que já tenha deixado a Presidência.","b":"RITJSP, art. 26, II, r"},
{"id":"tj_rit_050","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem recebe reclamações e instaura sindicância contra desembargadores?","v":"O Presidente do Tribunal, que atua como instrutor e relator até o arquivamento ou a instauração definitiva do processo administrativo.","b":"RITJSP, art. 26, II, z","p":"Contra juízes de primeiro grau, quem faz isso é o Corregedor Geral (art. 28, II)."},
{"id":"tj_rit_051","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem pratica os atos de provimento, férias, licença e aposentadoria dos servidores do Judiciário?","v":"O Presidente do Tribunal, salvo quando o Regimento atribuir a outro órgão.","b":"RITJSP, art. 26, II, u"},
{"id":"tj_rit_052","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem preside a distribuição dos processos do Órgão Especial?","v":"O Vice-Presidente, que também resolve previamente os incidentes e questões urgentes.","b":"RITJSP, art. 27, II, a"},
{"id":"tj_rit_053","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem secretaria os trabalhos do Conselho Superior da Magistratura?","v":"O Vice-Presidente do Tribunal.","b":"RITJSP, art. 27, II, c"},
{"id":"tj_rit_054","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Em caso de urgência, quem despacha, até a distribuição, MS, HC e HD contra ato do Presidente ou do Corregedor Geral?","v":"O Vice-Presidente.","b":"RITJSP, art. 27, I, c"},
{"id":"tj_rit_055","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem executa as decisões nos processos de competência originária do Órgão Especial?","v":"O Presidente, quando houver interesse das Fazendas Públicas e autarquias; nos demais casos, o Vice-Presidente.","b":"RITJSP, arts. 26, I, g, e 27, I, e"},
{"id":"tj_rit_056","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem superintende a distribuição dos feitos na primeira instância?","v":"O Corregedor Geral da Justiça, baixando as instruções necessárias.","b":"RITJSP, art. 28, I","p":"No segundo grau, a distribuição é presidida pelo Vice (Órgão Especial) e pelos Presidentes das Seções."},
{"id":"tj_rit_057","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem estabelece as normas de serviço das serventias judiciais e das delegações notariais e de registro?","v":"O Corregedor Geral da Justiça.","b":"RITJSP, art. 28, XVI e XXXI"},
{"id":"tj_rit_058","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Qual o papel do Corregedor Geral quanto à pena de demissão de servidor?","v":"Ele propõe a demissão à autoridade competente e aplica originariamente as demais penas, sem prejuízo dos corregedores permanentes.","b":"RITJSP, art. 28, XIV"},
{"id":"tj_rit_059","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem julga recurso contra decisão do juiz corregedor permanente em matéria disciplinar do pessoal das serventias judiciais?","v":"O Corregedor Geral da Justiça.","b":"RITJSP, art. 28, XIII","p":"Recurso contra decisão originária do próprio Corregedor Geral nesses processos vai à Câmara Especial (art. 33, V)."},
{"id":"tj_rit_060","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quando o Corregedor Geral apresenta ao Órgão Especial o relatório das correições?","v":"No final do primeiro ano e no final do mandato.","b":"RITJSP, art. 28, XXIV"},
{"id":"tj_rit_061","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"O Corregedor Geral pode dispensar edital nas correições extraordinárias?","v":"Sim, e pode mandar notificar, no próprio ato da visita, autoridade ou funcionário para comparecer à sua presença.","b":"RITJSP, art. 28, X"},
{"id":"tj_rit_062","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"O que compete ao Decano?","v":"Exercer as substituições regimentais, desempenhar atribuições delegadas pelos cargos de direção (com aprovação do CSM e referendo do Órgão Especial) e integrar comissão permanente.","b":"RITJSP, art. 29"},
{"id":"tj_rit_063","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem elege o Ouvidor do TJSP e qual o mandato?","v":"O Órgão Especial, por dois anos coincidentes com o mandato do Presidente, permitida uma reeleição; inscrições por edital de dez dias.","b":"RITJSP, art. 29-A","p":"O Ouvidor é eleito pelo Órgão Especial, não pelo Tribunal Pleno."},
{"id":"tj_rit_064","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Por quanto tempo seguido alguém pode exercer a função de Ouvidor?","v":"No máximo quatro anos consecutivos; nova eleição só depois de passado o período de um mandato.","b":"RITJSP, art. 29-A, § 5º"},
{"id":"tj_rit_065","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quais são as Seções do Tribunal e que órgãos ficam fora delas?","v":"Seções de Direito Criminal, Privado e Público. A Câmara Especial e a Câmara Especial de Presidentes são desvinculadas das Seções.","b":"RITJSP, art. 30"},
{"id":"tj_rit_066","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Como são compostas as Turmas Especiais?","v":"Pelos dois desembargadores mais antigos de cada Câmara ordinária da mesma Seção ou Subseção. A Turma pode reduzir para um por Câmara e voltar à composição original a qualquer tempo.","b":"RITJSP, art. 31"},
{"id":"tj_rit_067","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"O que compete às Turmas Especiais?","v":"Uniformizar a jurisprudência (inclusive IRDR) e a assunção de competência em matéria exclusiva da Seção, julgar reclamações contra seus acórdãos e as dúvidas e conflitos entre suas Câmaras e Grupos.","b":"RITJSP, art. 32"},
{"id":"tj_rit_068","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Como é o Grupo Especial da Seção de Direito Privado e o que decide?","v":"Nove desembargadores, os três mais antigos de cada Turma Especial. Decide conflitos de competência entre as Subseções de Direito Privado.","b":"RITJSP, art. 32, § 1º"},
{"id":"tj_rit_069","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem preside e quem integra a Câmara Especial?","v":"É presidida pelo Vice-Presidente e integrada pelos Presidentes das Seções e pelo Decano.","b":"RITJSP, art. 33","p":"A Câmara Especial de Presidentes é presidida pelo Presidente do Tribunal e não inclui o Decano."},
{"id":"tj_rit_070","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"O que julga a Câmara Especial?","v":"Suspeição e impedimento de juiz de primeiro grau; conflitos de competência entre juízes e de atribuição (salvo os do Órgão Especial); processos e recursos da Infância e Juventude; e recursos das decisões originárias do Corregedor Geral em processos disciplinares de servidores, delegados e oficiais de justiça.","b":"RITJSP, art. 33, parágrafo único"},
{"id":"tj_rit_071","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem integra a Câmara Especial de Presidentes e o que ela julga?","v":"Presidente do Tribunal (que preside), Vice-Presidente e Presidentes das Seções. Julga agravos internos contra decisões que negam seguimento ou sobrestam recurso especial ou extraordinário.","b":"RITJSP, art. 33-A"},
{"id":"tj_rit_072","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quantos desembargadores compõem cada Câmara e quantos julgam cada feito?","v":"Cada Câmara tem cinco desembargadores; os feitos são julgados por turma de três. Os cinco atuam nos embargos infringentes criminais e no julgamento ampliado do art. 942 do CPC.","b":"RITJSP, arts. 34 e 41","p":"Cinco integrantes, turma julgadora de três."},
{"id":"tj_rit_073","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Como são preenchidas as câmaras temporárias (reservadas)?","v":"O Presidente designa os titulares e três suplentes, depois de eleição pelo Órgão Especial entre candidatos inscritos.","b":"RITJSP, art. 34, § 2º"},
{"id":"tj_rit_074","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"O que as Câmaras julgam?","v":"Recursos contra decisões de primeiro grau, embargos de declaração e infringentes criminais contra seus acórdãos, rescisórias, reclamações, agravos internos e regimentais, habeas corpus, mandados de segurança e outros feitos originários.","b":"RITJSP, art. 35"},
{"id":"tj_rit_075","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Como se formam os Grupos de Câmaras?","v":"Pela reunião de duas Câmaras, em ordem crescente; se o número for ímpar, o primeiro ou o último Grupo terá três Câmaras.","b":"RITJSP, art. 36"},
{"id":"tj_rit_076","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"A que Grupo são distribuídas as revisões criminais de acórdãos?","v":"A um Grupo cujas Câmaras não tenham decidido em nenhuma fase do processo.","b":"RITJSP, art. 37, § 2º"},
{"id":"tj_rit_077","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Por quanto tempo são eleitos os presidentes das Turmas Especiais, Grupos e Câmaras?","v":"Pelo período que os integrantes acordarem, de seis meses a um ano, com alternância entre as Câmaras no Grupo.","b":"RITJSP, art. 38"},
{"id":"tj_rit_078","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Qual o quórum do Grupo nos feitos contra acórdão de Câmara e contra acórdão do próprio Grupo?","v":"Sete juízes quando o objeto é ato ou acórdão da Câmara (inclusive rescisória de apelação); nove quando é ato ou acórdão do Grupo.","b":"RITJSP, art. 40, IV"},
{"id":"tj_rit_079","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Havendo empate no Órgão Especial depois de todos votarem, o que se faz?","v":"Convoca-se o desembargador mais antigo que não integre o Órgão Especial para o voto de desempate.","b":"RITJSP, art. 39, § 2º"},
{"id":"tj_rit_080","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Qual o quórum para instalar as sessões do Órgão Especial, Turmas Especiais, Grupos e Câmaras?","v":"Maioria absoluta de seus integrantes.","b":"RITJSP, art. 43"},
{"id":"tj_rit_081","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Se o quórum qualificado não for alcançado, o que ocorre?","v":"O julgamento é adiado e convocam-se os desembargadores em exercício que não estavam presentes.","b":"RITJSP, art. 44"},
{"id":"tj_rit_082","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"O que compete aos Presidentes das Seções?","v":"Presidir a Seção, dirigir a distribuição, decidir urgências antes da distribuição, processar recursos especial e extraordinário da Seção e executar acórdãos originários das Turmas, Grupos e Câmaras.","b":"RITJSP, art. 45"},
{"id":"tj_rit_083","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Qual o prazo para as comissões permanentes darem parecer?","v":"Sessenta dias, se outro não for fixado ou não houver prorrogação pelo Órgão Especial.","b":"RITJSP, art. 46, § 2º"},
{"id":"tj_rit_084","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Salvo regra específica, quantos desembargadores compõem uma comissão permanente?","v":"Três desembargadores.","b":"RITJSP, art. 46, § 5º"},
{"id":"tj_rit_085","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem preside a Comissão de Jurisprudência e como ela é composta?","v":"O Decano, com seis desembargadores, dois de cada Seção; um deles, escolhido pelo Presidente, é o Supervisor da Biblioteca.","b":"RITJSP, art. 49"},
{"id":"tj_rit_086","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Como é composta a Comissão de Honraria e Mérito?","v":"Pelo Presidente do Tribunal e pelos quatro desembargadores mais antigos.","b":"RITJSP, art. 48"},
{"id":"tj_rit_087","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem preside a Comissão de Assuntos Administrativos e a CEJAI?","v":"Assuntos Administrativos: o Vice-Presidente (com cinco desembargadores e três juízes de entrância final). CEJAI (adoção internacional): o Corregedor Geral.","b":"RITJSP, arts. 52 e 56"},
{"id":"tj_rit_088","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Como é votada a lista tríplice do quinto constitucional?","v":"Em até três escrutínios, por votação secreta, exigida maioria absoluta em todos. No empate, prefere-se quem tem maior prática forense e, depois, o mais idoso.","b":"RITJSP, art. 58"},
{"id":"tj_rit_089","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Desembargador pode ser removido ou permutar de Câmara?","v":"Sim, para Câmara da mesma ou de outra Seção, com aprovação do Órgão Especial. Com vários pedidos para a mesma vaga, prefere o mais antigo que requerer antes do início da sessão.","b":"RITJSP, art. 60"},
{"id":"tj_rit_090","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Na remoção ou permuta, o que acontece com o acervo do desembargador?","v":"Ele assume o acervo e as prevenções da nova cadeira, mas continua vinculado aos feitos em que lançou visto na anterior.","b":"RITJSP, arts. 61 e 68"},
{"id":"tj_rit_091","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"De quando se conta a antiguidade do desembargador no Tribunal e como se desempata?","v":"Da posse. No empate, vale a antiguidade na entrância anterior, depois na carreira e, por fim, a maior idade.","b":"RITJSP, art. 62, § 1º"},
{"id":"tj_rit_092","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem não pode participar do mesmo Grupo ou Câmara?","v":"Cônjuges, conviventes e parentes consanguíneos ou afins em linha reta e, na colateral, até o terceiro grau, inclusive.","b":"RITJSP, art. 63"},
{"id":"tj_rit_093","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Como se resolve a incompatibilidade por parentesco antes e depois da posse?","v":"Antes da posse, contra o último nomeado (mesma data: o menos idoso). Depois, contra quem lhe deu causa; se ambos, contra o mais moderno.","b":"RITJSP, art. 63, § 1º"},
{"id":"tj_rit_094","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem concede licenças e afastamentos aos desembargadores?","v":"O Órgão Especial, mediante pedido escrito.","b":"RITJSP, art. 64"},
{"id":"tj_rit_095","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Como é concedida a licença para tratamento de saúde do desembargador?","v":"Até trinta dias com atestado médico. Prorrogações e licenças maiores dependem de perícia médica designada pelo Presidente.","b":"RITJSP, art. 64, § 1º"},
{"id":"tj_rit_096","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Qual o prazo máximo de afastamento para missão de relevância de interesse do Tribunal?","v":"Noventa dias, por deliberação do Órgão Especial.","b":"RITJSP, art. 65"},
{"id":"tj_rit_097","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Integrante do Órgão Especial afastado das funções judicantes pode votar matéria administrativa?","v":"Sim, se comunicar ao Presidente com setenta e duas horas de antecedência.","b":"RITJSP, art. 67"},
{"id":"tj_rit_098","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Se o afastamento do desembargador passar de quinze dias, o que se faz?","v":"Designa-se juiz substituto em segundo grau ou juiz de entrância final para assumir a cadeira.","b":"RITJSP, art. 70, § 2º"},
{"id":"tj_rit_099","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Há distribuição de feitos ao desembargador que vai se aposentar?","v":"Não nos trinta dias que antecedem a aposentadoria.","b":"RITJSP, art. 71"},
{"id":"tj_rit_100","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Em que casos há compensação de processos na distribuição?","v":"Prevenção, impedimento, suspeição, redistribuição de processo convertido em diligência, afastamento do relator sem redigir o acórdão e desembargador que não participa do julgamento em que lançou visto ou pediu adiamento.","b":"RITJSP, art. 69"},
{"id":"tj_rit_101","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Como se firma a competência dos órgãos do Tribunal?","v":"Pelos termos do pedido inicial, mesmo que haja reconvenção ou o réu alegue fatos que possam modificá-la.","b":"RITJSP, art. 103"},
{"id":"tj_rit_102","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Qual a regra geral de prevenção?","v":"A Câmara ou Grupo que primeiro conhecer da causa ou de incidente, mesmo sem julgar o mérito, fica preventa para os feitos conexos, todos os recursos e a execução dos julgados.","b":"RITJSP, art. 105"},
{"id":"tj_rit_103","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"O afastamento dos juízes do julgamento anterior rompe a prevenção?","v":"Não. O novo processo é distribuído a quem os substituir ou assumir a cadeira vaga.","b":"RITJSP, art. 105, § 1º"},
{"id":"tj_rit_104","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Qual a prevenção do relator do primeiro recurso protocolado no Tribunal?","v":"Fica prevento para os recursos seguintes no mesmo processo ou em conexos, enquanto compuser ou auxiliar a Câmara ou o Grupo.","b":"RITJSP, art. 105, § 3º"},
{"id":"tj_rit_105","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"O julgamento de agravo em execução penal gera prevenção para quê?","v":"Apenas para os incidentes do processo em que foi interposto.","b":"RITJSP, art. 106"},
{"id":"tj_rit_106","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem é juiz certo por ter visto nos autos?","v":"O desembargador com visto nos autos ou que pediu adiamento do julgamento, inclusive quando o julgamento virtual é convertido em presencial, qualquer que seja o motivo da saída do órgão.","b":"RITJSP, art. 108, I"},
{"id":"tj_rit_107","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quando o desembargador deixa de ser juiz certo?","v":"Quando se afasta, a qualquer título, por mais de sessenta dias depois do visto ou do pedido de adiamento. Continua juiz certo, porém, nos processos distribuídos por prevenção.","b":"RITJSP, art. 109","p":"60 dias para perder a condição de juiz certo; 40 dias para substituir o revisor ausente (art. 134, § 1º)."},
{"id":"tj_rit_108","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Julgamento por câmara temporária ou extinta firma prevenção?","v":"Não, nem torna certos os juízes, salvo nos embargos de declaração, embargos infringentes criminais e conversão em diligência.","b":"RITJSP, art. 110"},
{"id":"tj_rit_109","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Na ação rescisória e na revisão criminal, quem fica impedido?","v":"Na rescisória, quem participou do julgamento rescindendo só fica impedido de ser relator. Na revisão criminal, não pode atuar quem decidiu no processo original.","b":"RITJSP, art. 112, §§ 2º e 3º"},
{"id":"tj_rit_110","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Despacho de mero impulso dado em primeira instância impede o desembargador?","v":"Não. Ele pode atuar no mesmo processo no Tribunal.","b":"RITJSP, art. 112, § 1º"},
{"id":"tj_rit_111","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"O que o Presidente faz com petição de suspeição manifestamente inconsistente?","v":"Manda arquivá-la; dessa decisão cabe agravo interno para o Órgão Especial.","b":"RITJSP, art. 113"},
{"id":"tj_rit_112","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Em que horário se realizam as sessões do Tribunal?","v":"Entre nove e dezessete horas dos dias úteis, com prorrogação quando o serviço exigir.","b":"RITJSP, art. 116"},
{"id":"tj_rit_113","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Com que periodicidade o Órgão Especial e as Câmaras ordinárias fazem sessões presenciais?","v":"Semanalmente, facultada periodicidade maior, não superior a um mês.","b":"RITJSP, art. 116, § 1º"},
{"id":"tj_rit_114","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"O que acontece de 20 de dezembro a 20 de janeiro?","v":"Os prazos processuais ficam suspensos e não há audiências nem sessões de julgamento. Até 6 de janeiro o expediente funciona em regime de plantão.","b":"RITJSP, art. 116, § 2º","p":"O período vai de 20/12 a 20/01, inclusive; o plantão vai só até 6/01."},
{"id":"tj_rit_115","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Além dos prazos, o que mais fica suspenso entre 20/12 e 20/01?","v":"A publicação de acórdãos, sentenças e decisões e a intimação de partes ou advogados, nas duas instâncias, salvo medidas urgentes.","b":"RITJSP, art. 116, § 3º"},
{"id":"tj_rit_116","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quanto tempo se espera o magistrado que não chegou à audiência?","v":"Trinta minutos após a hora marcada; depois disso os presentes podem se retirar, registrando o fato em livro próprio.","b":"RITJSP, art. 118"},
{"id":"tj_rit_117","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quando as atas são aprovadas?","v":"Na sessão subsequente do órgão colegiado.","b":"RITJSP, art. 120"},
{"id":"tj_rit_118","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Qual o prazo para reclamar de erro em ata e qual o efeito?","v":"Quarenta e oito horas da publicação ou, sem ela, da aprovação. A reclamação não suspende o prazo de recurso; se acolhida, os dias faltantes são restituídos.","b":"RITJSP, art. 122"},
{"id":"tj_rit_119","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quais julgamentos independem de pauta?","v":"Habeas corpus, desaforamento, conflitos de jurisdição, competência ou atribuição e embargos de declaração em matéria criminal.","b":"RITJSP, art. 123, § 3º"},
{"id":"tj_rit_120","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Embargos de declaração em matéria não criminal precisam de pauta?","v":"Não, se julgados na sessão subsequente; se não forem, entram automaticamente em pauta.","b":"RITJSP, art. 123, § 4º"},
{"id":"tj_rit_121","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Se a sessão cair em feriado, o que acontece com os feitos pautados?","v":"Salvo deliberação em contrário, são julgados na sessão ordinária seguinte, sem nova publicação.","b":"RITJSP, art. 124"},
{"id":"tj_rit_122","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Com que antecedência a pauta de julgamento é publicada?","v":"Pelo menos cinco dias antes da sessão; uma cópia é afixada na porta da sala com no mínimo quinze minutos de antecedência e entregue a cada desembargador.","b":"RITJSP, art. 127"},
{"id":"tj_rit_123","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Que preferência tem o incidente de resolução de demandas repetitivas na pauta?","v":"Prefere aos demais feitos, exceto os de réu preso e os habeas corpus.","b":"RITJSP, art. 128, I"},
{"id":"tj_rit_124","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Como é a pauta da matéria administrativa e disciplinar do Órgão Especial?","v":"Pauta autônoma, publicada por extrato só com os números dos feitos e os nomes dos advogados.","b":"RITJSP, art. 130"},
{"id":"tj_rit_125","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Pode haver julgamento sem o relator?","v":"Não, ainda que ele já tenha votado, salvo se ele se afastar depois de iniciado o julgamento; nesse caso, computam-se os votos já dados.","b":"RITJSP, art. 134"},
{"id":"tj_rit_126","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"A ausência do revisor que ainda não votou adia o julgamento?","v":"Sim, salvo se o afastamento for superior a quarenta dias, quando ele é substituído.","b":"RITJSP, art. 134, § 1º","p":"A ausência ocasional de vogal não adia, se houver substituto (§ 2º)."},
{"id":"tj_rit_127","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quantas vezes cada desembargador pode falar no julgamento?","v":"Duas vezes sobre a matéria e mais uma para justificar mudança de voto. O relator pode falar sempre que necessário.","b":"RITJSP, art. 135, §§ 4º e 5º"},
{"id":"tj_rit_128","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Em matéria criminal, como se resolve a divergência sobre a pena sem maioria?","v":"Os votos pela pena mais grave somam-se aos da imediatamente inferior até formar maioria. Persistindo o empate, vota o presidente, se não votou; caso contrário, prevalece a decisão mais favorável ao réu.","b":"RITJSP, art. 139, § 2º"},
{"id":"tj_rit_129","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Havendo empate no julgamento de agravo, qual o resultado?","v":"Considera-se mantida a decisão agravada.","b":"RITJSP, art. 139, § 3º, III"},
{"id":"tj_rit_130","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Até quando o desembargador pode retificar ou modificar seu voto?","v":"Até a proclamação do resultado.","b":"RITJSP, art. 141"},
{"id":"tj_rit_131","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Com que antecedência deve ser feita a inscrição prévia por e-mail para sustentação oral?","v":"No mínimo vinte e quatro horas antes da hora prevista para o início da sessão. Sem inscrição prévia, ainda é possível pedir até o início da sessão, no local.","b":"RITJSP, art. 146, II e III"},
{"id":"tj_rit_132","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Pode-se adiar o julgamento para fazer sustentação oral?","v":"Sim, por uma sessão, por decisão do relator, com justificativa comprovada apresentada até o início da sessão.","b":"RITJSP, art. 146, § 1º"},
{"id":"tj_rit_133","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Em que julgamentos não cabe sustentação oral?","v":"Embargos de declaração, incidente de suspeição, conflito de competência, arquivamento de inquérito ou representação criminal e agravo — salvo o de instrumento sobre tutela de urgência ou evidência e o interno contra extinção de feito originário.","b":"RITJSP, art. 146, § 4º"},
{"id":"tj_rit_134","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Qual o tempo máximo de sustentação oral no agravo em execução penal?","v":"Cinco minutos.","b":"RITJSP, art. 146, § 4º-A"},
{"id":"tj_rit_135","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Até quando o advogado deve pedir sustentação oral por videoconferência?","v":"Até o dia anterior ao da sessão.","b":"RITJSP, art. 146, § 5º"},
{"id":"tj_rit_136","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Qual a ordem das sustentações orais no mesmo processo?","v":"Fala primeiro o autor ou impetrante (nos originários) ou o recorrente (nos recursos); o Ministério Público fala por último, quando não for autor ou recorrente. O interveniente também fala por último.","b":"RITJSP, art. 147"},
{"id":"tj_rit_137","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Em que ordem votam os julgadores?","v":"Relator, revisor (se houver) e depois os demais em ordem de antiguidade.","b":"RITJSP, art. 152"},
{"id":"tj_rit_138","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quando o Presidente do Tribunal vota nas sessões que preside?","v":"Em matéria constitucional, para desempate em qualquer matéria e quando for relator nato.","b":"RITJSP, art. 153"},
{"id":"tj_rit_139","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Qual a regra geral de quórum de deliberação no Tribunal?","v":"Maioria simples, salvo disposição em contrário.","b":"RITJSP, art. 154"},
{"id":"tj_rit_140","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Vencido o relator, quem redige o acórdão?","v":"O desembargador designado, de preferência o que primeiro expôs a tese vencedora.","b":"RITJSP, art. 155"},
{"id":"tj_rit_141","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Se o redator do acórdão morrer, se aposentar ou se afastar por mais de sessenta dias sem assinar, quem assina?","v":"O desembargador que, com voto vencedor, o seguiu imediatamente na ordem de votação.","b":"RITJSP, art. 160"},
{"id":"tj_rit_142","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Em que prazo as conclusões do acórdão são publicadas para intimação?","v":"Nos cinco dias seguintes ao registro.","b":"RITJSP, art. 163"},
{"id":"tj_rit_143","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Qual o prazo do relator e do revisor para examinar os autos e votar?","v":"Trinta dias, salvo outro prazo estabelecido.","b":"RITJSP, art. 172"},
{"id":"tj_rit_144","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Qual o prazo para devolver os autos após pedido de vista?","v":"Até dez dias, prorrogáveis por no máximo mais dez a pedido ao presidente do órgão (no Órgão Especial, ao Presidente do Tribunal). Devolvidos, o feito entra automaticamente na pauta da sessão seguinte.","b":"RITJSP, art. 173","p":"Vista: 10 + 10 dias; relator e revisor: 30 dias (art. 172)."},
{"id":"tj_rit_145","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"E se os autos da vista não forem devolvidos no prazo?","v":"O presidente do órgão (ou do Tribunal, no Órgão Especial) os requisita para a sessão seguinte. Quem pediu vista vota; se não se sentir habilitado, é substituído.","b":"RITJSP, art. 173, §§ 1º e 2º"},
{"id":"tj_rit_146","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Qual o prazo para remessa e apresentação dos feitos no Tribunal?","v":"Quarenta e oito horas se urgentes; cinco dias nos demais casos. Na remessa pelo correio, vale a data da postagem.","b":"RITJSP, art. 175"},
{"id":"tj_rit_147","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Como os feitos são distribuídos aos desembargadores?","v":"Em audiência pública, em dias certos da semana, por cadeira, mediante sorteio ininterrupto e paritário, respeitadas prevenções e impedimentos.","b":"RITJSP, art. 181"},
{"id":"tj_rit_148","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"No Órgão Especial, quem não recebe distribuição?","v":"Presidente, Vice-Presidente e Corregedor Geral da Justiça.","b":"RITJSP, art. 181-A"},
{"id":"tj_rit_149","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem decide reclamação contra irregularidade na distribuição?","v":"O Vice-Presidente ou os Presidentes de Seção, conforme o caso. A redistribuição cancela a anterior, com compensação.","b":"RITJSP, art. 182"},
{"id":"tj_rit_150","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Qual o prazo do Ministério Público para se manifestar no Tribunal?","v":"Dez dias ou, havendo urgência, cinco, salvo previsão legal.","b":"RITJSP, art. 186, parágrafo único"},
{"id":"tj_rit_151","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Até quando é publicada a estatística mensal?","v":"Até o dia quinze de cada mês ou o primeiro dia útil seguinte. Depois, o Presidente da Seção tem três dias para comunicar atrasos dos desembargadores.","b":"RITJSP, arts. 188 e 189"},
{"id":"tj_rit_152","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem aprova as súmulas do TJSP e com que quórum?","v":"Exclusivamente o Órgão Especial, por maioria simples dos membros; o presidente da sessão tem voto de qualidade.","b":"RITJSP, arts. 190, § 1º, e 191"},
{"id":"tj_rit_153","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Por quanto tempo o processo fica suspenso após suscitado conflito de competência?","v":"No máximo noventa dias; o relator decide as medidas urgentes ou designa quem o fará.","b":"RITJSP, art. 201"},
{"id":"tj_rit_154","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Cabe recurso da decisão de conflito de atribuição?","v":"Não.","b":"RITJSP, art. 228"},
{"id":"tj_rit_155","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Qual o quórum no julgamento de ação direta de inconstitucionalidade?","v":"Presença de dois terços do Órgão Especial; a inconstitucionalidade é declarada por maioria absoluta dos membros.","b":"RITJSP, art. 231","p":"Dois terços é o quórum de presença; para declarar, maioria absoluta."},
{"id":"tj_rit_156","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quando cabe correição parcial e qual o seu rito?","v":"No processo penal, contra erro ou abuso que inverta tumultuariamente os atos processuais, sem recurso específico. Segue o rito do agravo de instrumento do CPC, ouvido o Procurador-Geral de Justiça.","b":"RITJSP, arts. 211 e 212"},
{"id":"tj_rit_157","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Qual o prazo e o efeito do agravo regimental?","v":"Quinze dias, sem efeito suspensivo, contra decisões monocráticas que possam prejudicar o direito da parte.","b":"RITJSP, art. 253","p":"Contra o indeferimento de intervenção federal pelo Presidente, o agravo regimental é de cinco dias (art. 262)."},
{"id":"tj_rit_158","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Faltando peça no agravo, que prazo tem o agravante?","v":"Cinco dias para completar a documentação ou sanar o vício.","b":"RITJSP, art. 254"},
{"id":"tj_rit_159","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"O que pode fazer quem proferiu a decisão agravada?","v":"Reconsiderá-la; se a mantiver, leva o feito à Mesa, sem inclusão em pauta, e vota.","b":"RITJSP, art. 255"},
{"id":"tj_rit_160","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem examina a admissibilidade de recursos ao STF e tribunais superiores?","v":"O Presidente do Tribunal, se o acórdão for do Órgão Especial; nos demais casos, o Presidente da respectiva Seção.","b":"RITJSP, art. 256"},
{"id":"tj_rit_161","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Cabe agravo interno da decisão do Presidente em pedido de sequestro de precatório?","v":"Não.","b":"RITJSP, art. 269"},
{"id":"tj_rit_162","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Por quais atos o Órgão Especial e o Conselho Superior da Magistratura se manifestam administrativamente?","v":"Órgão Especial: resoluções e assentos. Conselho Superior da Magistratura: provimentos e pareceres.","b":"RITJSP, art. 271, I e II"},
{"id":"tj_rit_163","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Que atos expedem Presidente, Vice, Corregedor Geral e Presidentes de Seções?","v":"Decisões, despachos, provimentos, instruções, portarias e comunicados. As comissões expedem pareceres; os juízes corregedores, despachos e pareceres.","b":"RITJSP, art. 271, III a V"},
{"id":"tj_rit_164","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"O que é resolução?","v":"Ato do Órgão Especial sobre propostas de lei de sua iniciativa e providências normativas relevantes do Judiciário e do Tribunal.","b":"RITJSP, art. 271, § 1º"},
{"id":"tj_rit_165","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"O que é assento?","v":"Ato do Órgão Especial para interpretar, compreender e alterar normas regimentais.","b":"RITJSP, art. 271, § 2º","p":"Mudança no Regimento se faz por assento, não por resolução."},
{"id":"tj_rit_166","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"O que é provimento?","v":"Instrução ou determinação de caráter regulamentar para a boa ordem, regularidade e uniformização dos serviços da Justiça e fiel observância da lei.","b":"RITJSP, art. 271, § 3º"},
{"id":"tj_rit_167","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"O que é instrução, como ato administrativo?","v":"Ato de ordenamento interno que disciplina o modo de executar os serviços da Secretaria do Tribunal e dos órgãos auxiliares.","b":"RITJSP, art. 271, § 6º"},
{"id":"tj_rit_168","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Para que serve a portaria?","v":"Ato interno para convocar e designar magistrado; nomear, admitir coletivamente e movimentar servidores; estruturar ou reestruturar serviços; e instaurar procedimento disciplinar ou de outra natureza.","b":"RITJSP, art. 271, § 7º"},
{"id":"tj_rit_169","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"O que são parecer, despacho e comunicado?","v":"Parecer: ato consultivo que orienta decisão administrativa. Despacho: pronunciamento decisório ou de impulso. Comunicado: aviso oficial sobre matéria processual ou administrativa relevante.","b":"RITJSP, art. 271, §§ 4º, 5º e 8º"},
{"id":"tj_rit_170","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Como são numerados os atos administrativos do Tribunal?","v":"Cronologicamente, segundo a classe e a ordem de expedição no ano.","b":"RITJSP, art. 271, § 9º"},
{"id":"tj_rit_171","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem pode propor alteração do Regimento Interno?","v":"O Conselho Superior da Magistratura, os órgãos judicantes, a Comissão de Regimento Interno e qualquer desembargador, sempre por escrito e com exposição de motivos.","b":"RITJSP, art. 272"},
{"id":"tj_rit_172","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Em que prazo a Comissão de Regimento Interno opina sobre proposta que não é dela?","v":"Em prazo não superior a trinta dias.","b":"RITJSP, art. 273"},
{"id":"tj_rit_173","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Qual o quórum para alterar o Regimento Interno?","v":"Voto de dois terços dos integrantes do Órgão Especial.","b":"RITJSP, art. 277","p":"Dois terços dos integrantes (não dos presentes) e não maioria absoluta."},
{"id":"tj_rit_174","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Havendo urgência, a reforma do Regimento pode dispensar o procedimento?","v":"Sim, o Órgão Especial pode dispensá-lo, mantido o quórum de dois terços.","b":"RITJSP, art. 278"},
{"id":"tj_rit_175","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Com que frequência o Regimento Interno é publicado no órgão oficial?","v":"A cada dois anos; fica também disponível no site do Tribunal.","b":"RITJSP, art. 279"},
{"id":"tj_rit_176","d":"Legislação Interna","t":"Regimento Interno do TJSP","f":"Quem resolve os casos omissos do Regimento?","v":"O Órgão Especial, ouvida a Comissão de Regimento Interno.","b":"RITJSP, art. 287"}
]);
